(* [comment removed for export] *)
Definition arm_at (pc c : Z) : Prop :=
  forall rax a0x a1x a2x ra sp gp tp t0 t1 t2 s1 a3 a4 a5 a6 a7 s0v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P : Z) (bs : list byte) (lo : Z) (b0 : byte) (rest : list byte),
  verb_ctx m m1 sp s0v ra P bs (P + 1) (Z.of_nat (length bs) - 1) lo -> verb_pure sp P bs lo ->
  bs = b0 :: rest -> (2 <= length rest)%nat -> zb b0 = c ->
  evt rsegs (string_to_verb_post ra sp gp tp s0v s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P bs lo m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2 (wz c) s1 a0x a1x a2x a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom rsegs)).

End HCW.

Ltac arm_intro :=
  intros rax a0x a1x a2x ra sp gp tp t0 t1 t2 s1 a3 a4 a5 a6 a7 s0v s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m m1 P bs lo b0 rest;
  intros CTX PURE HBS HL HC;
  pose proof CTX as CTX'; pose proof PURE as PURE'; open_verb CTX' PURE';
  (assert (HLEN : length bs = S (length rest)) by (rewrite HBS; reflexivity));
  lazymatch goal with W : bytes_at _ m1 P bs |- _ =>
    assert (WR : bytes_at rsegs m1 (P + 1) rest) by (rewrite HBS in W; exact (bytes_at_tail _ _ _ _ W)) end;
  unfold wz in *.

(* [comment removed for export] *)
Ltac dtests :=
  cbn [zbytes map lzeqb andb orb negb L_CL L_ET L_ST L_PY L_VE L_OL L_T L_RACE L_BIND L_PORT L_LINK L_LOCK
       L_EARCH L_IND L_ECKOUT L_ELETE L_EAD L_NNECT L_PTIONS L_OTIFY L_INK L_UBSCRIBE L_OCK L_TCH L_RGE L_ALENDAR
       L_ACTIVITY L_OPPATCH L_SUBSCRIBE L_SEARCH L_OPFIND];
  repeat (match goal with
          | |- context [?x =? ?y] =>
              first [ rewrite (proj2 (Z.eqb_eq x y)) by lia
                    | rewrite (proj2 (Z.eqb_neq x y)) by lia
                    | destruct (Z.eqb_spec x y) ];
              cbn [andb orb negb]
          end);
  first [ reflexivity | lia | exfalso; lia ].

